-- SEC-090 Community / Bairro Rural Conectado
-- DEV first. Community never grants neighborhood admins access to private farm devices.
CREATE TABLE IF NOT EXISTS public.community_participation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), neighborhood_id uuid NOT NULL REFERENCES public.neighborhoods(id), property_id uuid NOT NULL UNIQUE REFERENCES public.properties(id), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','left')), route_points_enabled boolean NOT NULL DEFAULT true, community_alerts_enabled boolean NOT NULL DEFAULT true, activated_by_user_id uuid NOT NULL REFERENCES public.app_users(id), activated_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.community_sharing_rules (neighborhood_id uuid PRIMARY KEY REFERENCES public.neighborhoods(id), organization_id uuid NOT NULL REFERENCES public.organizations(id), community_events_visible boolean NOT NULL DEFAULT true, route_points_enabled boolean NOT NULL DEFAULT true, private_device_sharing_allowed boolean NOT NULL DEFAULT false CHECK (private_device_sharing_allowed=false), updated_by_user_id uuid NOT NULL REFERENCES public.app_users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.community_route_points (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), neighborhood_id uuid NOT NULL REFERENCES public.neighborhoods(id), property_id uuid NOT NULL REFERENCES public.properties(id), device_id uuid NOT NULL REFERENCES public.devices(id), sequence_no integer NOT NULL DEFAULT 0 CHECK(sequence_no BETWEEN 0 AND 1000), enabled boolean NOT NULL DEFAULT true, created_by_user_id uuid NOT NULL REFERENCES public.app_users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(property_id,device_id));
CREATE TABLE IF NOT EXISTS public.community_maintenance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), neighborhood_id uuid NOT NULL REFERENCES public.neighborhoods(id), device_id uuid NOT NULL REFERENCES public.devices(id), title text NOT NULL CHECK(length(title) BETWEEN 3 AND 160), description text NULL CHECK(description IS NULL OR length(description)<=4000), priority text NOT NULL DEFAULT 'attention' CHECK(priority IN ('attention','high','critical')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved','closed')), created_by_user_id uuid NOT NULL REFERENCES public.app_users(id), assigned_user_id uuid NULL REFERENCES public.app_users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz NULL);
CREATE INDEX IF NOT EXISTS idx_community_participation_neighborhood_status ON public.community_participation(neighborhood_id,status);CREATE INDEX IF NOT EXISTS idx_community_route_property_sequence ON public.community_route_points(property_id,sequence_no);CREATE INDEX IF NOT EXISTS idx_community_maintenance_neighborhood_status ON public.community_maintenance(neighborhood_id,status,priority);
ALTER TABLE public.community_participation ENABLE ROW LEVEL SECURITY;ALTER TABLE public.community_sharing_rules ENABLE ROW LEVEL SECURITY;ALTER TABLE public.community_route_points ENABLE ROW LEVEL SECURITY;ALTER TABLE public.community_maintenance ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.community_participation,public.community_sharing_rules,public.community_route_points,public.community_maintenance FROM authenticated;
COMMENT ON COLUMN public.community_sharing_rules.private_device_sharing_allowed IS 'MVP invariant: private farm devices are never shared through Community. Must remain false.';COMMENT ON TABLE public.community_route_points IS 'Per-property route references only community_shared cameras from the same neighborhood; never private cameras.';
CREATE OR REPLACE FUNCTION public.app_is_property_owner(p_property_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','auth' AS $$ SELECT EXISTS(SELECT 1 FROM public.memberships m JOIN public.app_users u ON u.id=m.user_id WHERE m.property_id=p_property_id AND m.role='owner' AND m.status='active' AND u.status='active' AND u.auth_user_id=NULLIF(auth.user_id(),'')::uuid) $$;
CREATE OR REPLACE FUNCTION public.app_is_neighborhood_admin(p_neighborhood_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','auth' AS $$ SELECT public.app_is_platform_admin() OR EXISTS(SELECT 1 FROM public.neighborhoods n JOIN public.memberships m ON m.organization_id=n.organization_id JOIN public.app_users u ON u.id=m.user_id WHERE n.id=p_neighborhood_id AND m.status='active' AND u.status='active' AND u.auth_user_id=NULLIF(auth.user_id(),'')::uuid AND (m.role='admin_organization' OR (m.role='admin_neighborhood' AND m.neighborhood_id=p_neighborhood_id))) $$;
CREATE OR REPLACE FUNCTION public.app_has_community_access(p_neighborhood_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','auth' AS $$ SELECT public.app_is_neighborhood_admin(p_neighborhood_id) OR EXISTS(SELECT 1 FROM public.memberships m JOIN public.app_users u ON u.id=m.user_id JOIN public.community_participation cp ON cp.property_id=m.property_id AND cp.neighborhood_id=p_neighborhood_id AND cp.status='active' WHERE m.status='active' AND u.status='active' AND u.auth_user_id=NULLIF(auth.user_id(),'')::uuid) OR EXISTS(SELECT 1 FROM public.memberships m JOIN public.app_users u ON u.id=m.user_id WHERE m.neighborhood_id=p_neighborhood_id AND m.role='technician' AND m.status='active' AND u.status='active' AND u.auth_user_id=NULLIF(auth.user_id(),'')::uuid) $$;
CREATE OR REPLACE FUNCTION public.activate_my_community_participation(p_property_id uuid,p_route_points_enabled boolean DEFAULT true,p_community_alerts_enabled boolean DEFAULT true) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_org uuid;v_neighborhood uuid;v_user uuid;v_id uuid;BEGIN SELECT organization_id,neighborhood_id INTO v_org,v_neighborhood FROM public.properties WHERE id=p_property_id;IF v_org IS NULL OR v_neighborhood IS NULL THEN RAISE EXCEPTION 'property_neighborhood_required';END IF;IF NOT public.app_is_property_owner(p_property_id) THEN RAISE EXCEPTION 'property_owner_required';END IF;v_user:=public.app_current_user_id();IF v_user IS NULL THEN RAISE EXCEPTION 'active_user_required';END IF;INSERT INTO public.community_participation(organization_id,neighborhood_id,property_id,status,route_points_enabled,community_alerts_enabled,activated_by_user_id,activated_at,updated_at) VALUES(v_org,v_neighborhood,p_property_id,'active',p_route_points_enabled,p_community_alerts_enabled,v_user,now(),now()) ON CONFLICT(property_id) DO UPDATE SET status='active',route_points_enabled=EXCLUDED.route_points_enabled,community_alerts_enabled=EXCLUDED.community_alerts_enabled,activated_by_user_id=EXCLUDED.activated_by_user_id,activated_at=now(),updated_at=now() RETURNING id INTO v_id;INSERT INTO public.community_sharing_rules(neighborhood_id,organization_id,community_events_visible,route_points_enabled,private_device_sharing_allowed,updated_by_user_id) VALUES(v_neighborhood,v_org,true,true,false,v_user) ON CONFLICT(neighborhood_id) DO NOTHING;INSERT INTO public.audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,v_user,'community.participation.activated','property',p_property_id::text,jsonb_build_object('neighborhood_id',v_neighborhood,'route_points_enabled',p_route_points_enabled,'community_alerts_enabled',p_community_alerts_enabled));RETURN v_id;END $$;
CREATE OR REPLACE FUNCTION public.set_my_community_preferences(p_property_id uuid,p_route_points_enabled boolean,p_community_alerts_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_org uuid;v_user uuid;BEGIN IF NOT public.app_is_property_owner(p_property_id) THEN RAISE EXCEPTION 'property_owner_required';END IF;v_user:=public.app_current_user_id();UPDATE public.community_participation SET route_points_enabled=p_route_points_enabled,community_alerts_enabled=p_community_alerts_enabled,updated_at=now() WHERE property_id=p_property_id AND status='active' RETURNING organization_id INTO v_org;IF v_org IS NULL THEN RAISE EXCEPTION 'active_participation_required';END IF;INSERT INTO public.audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,v_user,'community.preferences.updated','property',p_property_id::text,jsonb_build_object('route_points_enabled',p_route_points_enabled,'community_alerts_enabled',p_community_alerts_enabled));END $$;
CREATE OR REPLACE FUNCTION public.leave_community(p_property_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_org uuid;v_user uuid;BEGIN IF NOT public.app_is_property_owner(p_property_id) THEN RAISE EXCEPTION 'property_owner_required';END IF;v_user:=public.app_current_user_id();UPDATE public.community_participation SET status='left',route_points_enabled=false,community_alerts_enabled=false,updated_at=now() WHERE property_id=p_property_id RETURNING organization_id INTO v_org;IF v_org IS NULL THEN RAISE EXCEPTION 'participation_not_found';END IF;UPDATE public.community_route_points SET enabled=false,updated_at=now() WHERE property_id=p_property_id;INSERT INTO public.audit_logs(organization_id,actor_user_id,action,entity_type,entity_id) VALUES(v_org,v_user,'community.participation.left','property',p_property_id::text);END $$;
CREATE OR REPLACE FUNCTION public.set_community_rules(p_neighborhood_id uuid,p_community_events_visible boolean,p_route_points_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_org uuid;v_user uuid;BEGIN IF NOT public.app_is_neighborhood_admin(p_neighborhood_id) THEN RAISE EXCEPTION 'neighborhood_admin_required';END IF;SELECT organization_id INTO v_org FROM public.neighborhoods WHERE id=p_neighborhood_id;v_user:=public.app_current_user_id();INSERT INTO public.community_sharing_rules(neighborhood_id,organization_id,community_events_visible,route_points_enabled,private_device_sharing_allowed,updated_by_user_id,updated_at) VALUES(p_neighborhood_id,v_org,p_community_events_visible,p_route_points_enabled,false,v_user,now()) ON CONFLICT(neighborhood_id) DO UPDATE SET community_events_visible=EXCLUDED.community_events_visible,route_points_enabled=EXCLUDED.route_points_enabled,private_device_sharing_allowed=false,updated_by_user_id=EXCLUDED.updated_by_user_id,updated_at=now();INSERT INTO public.audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,v_user,'community.rules.updated','neighborhood',p_neighborhood_id::text,jsonb_build_object('community_events_visible',p_community_events_visible,'route_points_enabled',p_route_points_enabled,'private_device_sharing_allowed',false));END $$;
CREATE OR REPLACE FUNCTION public.set_my_community_route_point(p_property_id uuid,p_device_id uuid,p_enabled boolean DEFAULT true,p_sequence_no integer DEFAULT 0) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_org uuid;v_neighborhood uuid;v_user uuid;v_id uuid;v_device_ok boolean;BEGIN IF NOT public.app_is_property_owner(p_property_id) THEN RAISE EXCEPTION 'property_owner_required';END IF;SELECT organization_id,neighborhood_id INTO v_org,v_neighborhood FROM public.properties WHERE id=p_property_id;IF NOT EXISTS(SELECT 1 FROM public.community_participation cp JOIN public.community_sharing_rules r ON r.neighborhood_id=cp.neighborhood_id WHERE cp.property_id=p_property_id AND cp.status='active' AND cp.route_points_enabled=true AND r.route_points_enabled=true) THEN RAISE EXCEPTION 'community_route_not_enabled';END IF;SELECT EXISTS(SELECT 1 FROM public.devices d WHERE d.id=p_device_id AND d.organization_id=v_org AND d.neighborhood_id=v_neighborhood AND d.property_id IS NULL AND d.area_id IS NULL AND d.community_shared=true AND d.device_type='camera') INTO v_device_ok;IF NOT v_device_ok THEN RAISE EXCEPTION 'community_camera_required';END IF;v_user:=public.app_current_user_id();INSERT INTO public.community_route_points(organization_id,neighborhood_id,property_id,device_id,sequence_no,enabled,created_by_user_id,updated_at) VALUES(v_org,v_neighborhood,p_property_id,p_device_id,p_sequence_no,p_enabled,v_user,now()) ON CONFLICT(property_id,device_id) DO UPDATE SET sequence_no=EXCLUDED.sequence_no,enabled=EXCLUDED.enabled,updated_at=now() RETURNING id INTO v_id;INSERT INTO public.audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,v_user,'community.route_point.updated','property',p_property_id::text,jsonb_build_object('device_id',p_device_id,'enabled',p_enabled,'sequence_no',p_sequence_no));RETURN v_id;END $$;
CREATE OR REPLACE FUNCTION public.get_path_to_property_points(p_property_id uuid) RETURNS TABLE(sequence_no integer,point_type text,device_id uuid,name text,status text,latitude double precision,longitude double precision) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_org uuid;v_neighborhood uuid;BEGIN SELECT organization_id,neighborhood_id INTO v_org,v_neighborhood FROM public.properties WHERE id=p_property_id;IF v_org IS NULL OR NOT public.app_has_scope_access(v_org,v_neighborhood,p_property_id) THEN RAISE EXCEPTION 'property_access_required';END IF;IF NOT EXISTS(SELECT 1 FROM public.community_participation cp JOIN public.community_sharing_rules r ON r.neighborhood_id=cp.neighborhood_id WHERE cp.property_id=p_property_id AND cp.status='active' AND cp.route_points_enabled=true AND r.route_points_enabled=true) THEN RAISE EXCEPTION 'community_route_not_enabled';END IF;RETURN QUERY SELECT rp.sequence_no,'community_camera'::text,d.id,d.name,d.status::text,ST_Y(d.location::geometry),ST_X(d.location::geometry) FROM public.community_route_points rp JOIN public.devices d ON d.id=rp.device_id WHERE rp.property_id=p_property_id AND rp.enabled=true AND d.community_shared=true AND d.property_id IS NULL AND d.neighborhood_id=v_neighborhood AND d.location IS NOT NULL UNION ALL SELECT 100000,'property'::text,NULL::uuid,p.name,'destination'::text,ST_Y(p.centroid::geometry),ST_X(p.centroid::geometry) FROM public.properties p WHERE p.id=p_property_id AND p.centroid IS NOT NULL ORDER BY 1;END $$;
CREATE OR REPLACE FUNCTION public.get_community_dashboard(p_neighborhood_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_result jsonb;BEGIN IF NOT public.app_has_community_access(p_neighborhood_id) THEN RAISE EXCEPTION 'community_access_required';END IF;SELECT jsonb_build_object('neighborhood_id',n.id,'name',n.name,'active_properties',(SELECT count(*) FROM public.community_participation cp WHERE cp.neighborhood_id=n.id AND cp.status='active'),'community_cameras',(SELECT count(*) FROM public.devices d WHERE d.neighborhood_id=n.id AND d.community_shared=true AND d.property_id IS NULL AND d.device_type='camera'),'online_cameras',(SELECT count(*) FROM public.devices d WHERE d.neighborhood_id=n.id AND d.community_shared=true AND d.property_id IS NULL AND d.device_type='camera' AND d.status='online'),'open_maintenance',(SELECT count(*) FROM public.community_maintenance cm WHERE cm.neighborhood_id=n.id AND cm.status IN ('open','in_progress')),'private_device_sharing_allowed',false) INTO v_result FROM public.neighborhoods n WHERE n.id=p_neighborhood_id;RETURN v_result;END $$;
CREATE OR REPLACE FUNCTION public.get_community_devices(p_neighborhood_id uuid) RETURNS TABLE(device_id uuid,name text,device_type text,status text,latitude double precision,longitude double precision,last_seen_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ BEGIN IF NOT public.app_has_community_access(p_neighborhood_id) THEN RAISE EXCEPTION 'community_access_required';END IF;RETURN QUERY SELECT d.id,d.name,d.device_type::text,d.status::text,CASE WHEN d.location IS NULL THEN NULL ELSE ST_Y(d.location::geometry) END,CASE WHEN d.location IS NULL THEN NULL ELSE ST_X(d.location::geometry) END,d.last_seen_at FROM public.devices d WHERE d.neighborhood_id=p_neighborhood_id AND d.community_shared=true AND d.property_id IS NULL ORDER BY d.name;END $$;
CREATE OR REPLACE FUNCTION public.get_community_participants(p_neighborhood_id uuid) RETURNS TABLE(property_id uuid,property_name text,status text,route_points_enabled boolean,community_alerts_enabled boolean,activated_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ BEGIN IF NOT public.app_is_neighborhood_admin(p_neighborhood_id) THEN RAISE EXCEPTION 'neighborhood_admin_required';END IF;RETURN QUERY SELECT p.id,p.name,cp.status,cp.route_points_enabled,cp.community_alerts_enabled,cp.activated_at FROM public.community_participation cp JOIN public.properties p ON p.id=cp.property_id WHERE cp.neighborhood_id=p_neighborhood_id ORDER BY p.name;END $$;
CREATE OR REPLACE FUNCTION public.report_community_maintenance(p_device_id uuid,p_title text,p_description text DEFAULT NULL,p_priority text DEFAULT 'attention') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_org uuid;v_neighborhood uuid;v_user uuid;v_id uuid;BEGIN SELECT organization_id,neighborhood_id INTO v_org,v_neighborhood FROM public.devices WHERE id=p_device_id AND community_shared=true AND property_id IS NULL;IF v_org IS NULL OR v_neighborhood IS NULL THEN RAISE EXCEPTION 'community_device_required';END IF;IF NOT public.app_has_community_access(v_neighborhood) THEN RAISE EXCEPTION 'community_access_required';END IF;IF p_priority NOT IN ('attention','high','critical') THEN RAISE EXCEPTION 'invalid_priority';END IF;v_user:=public.app_current_user_id();INSERT INTO public.community_maintenance(organization_id,neighborhood_id,device_id,title,description,priority,created_by_user_id) VALUES(v_org,v_neighborhood,p_device_id,trim(p_title),nullif(trim(p_description),''),p_priority,v_user) RETURNING id INTO v_id;INSERT INTO public.audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,v_user,'community.maintenance.reported','community_maintenance',v_id::text,jsonb_build_object('device_id',p_device_id,'priority',p_priority));RETURN v_id;END $$;
CREATE OR REPLACE FUNCTION public.update_community_maintenance_status(p_maintenance_id uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ DECLARE v_org uuid;v_neighborhood uuid;v_user uuid;BEGIN SELECT organization_id,neighborhood_id INTO v_org,v_neighborhood FROM public.community_maintenance WHERE id=p_maintenance_id;IF v_org IS NULL THEN RAISE EXCEPTION 'maintenance_not_found';END IF;IF NOT public.app_can_manage_neighborhood(v_neighborhood) THEN RAISE EXCEPTION 'community_maintenance_manage_required';END IF;IF p_status NOT IN ('open','in_progress','resolved','closed') THEN RAISE EXCEPTION 'invalid_status';END IF;v_user:=public.app_current_user_id();UPDATE public.community_maintenance SET status=p_status,assigned_user_id=CASE WHEN p_status='in_progress' THEN COALESCE(assigned_user_id,v_user) ELSE assigned_user_id END,resolved_at=CASE WHEN p_status IN ('resolved','closed') THEN COALESCE(resolved_at,now()) ELSE NULL END,updated_at=now() WHERE id=p_maintenance_id;INSERT INTO public.audit_logs(organization_id,actor_user_id,action,entity_type,entity_id,details) VALUES(v_org,v_user,'community.maintenance.status_updated','community_maintenance',p_maintenance_id::text,jsonb_build_object('status',p_status));END $$;
CREATE OR REPLACE FUNCTION public.get_community_maintenance(p_neighborhood_id uuid) RETURNS TABLE(id uuid,device_id uuid,device_name text,title text,description text,priority text,status text,assigned_user_id uuid,created_at timestamptz,updated_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ BEGIN IF NOT public.app_has_community_access(p_neighborhood_id) THEN RAISE EXCEPTION 'community_access_required';END IF;RETURN QUERY SELECT cm.id,cm.device_id,d.name,cm.title,cm.description,cm.priority,cm.status,cm.assigned_user_id,cm.created_at,cm.updated_at FROM public.community_maintenance cm JOIN public.devices d ON d.id=cm.device_id WHERE cm.neighborhood_id=p_neighborhood_id ORDER BY CASE cm.status WHEN 'open' THEN 0 WHEN 'in_progress' THEN 1 WHEN 'resolved' THEN 2 ELSE 3 END,cm.created_at DESC;END $$;
REVOKE ALL ON FUNCTION public.app_is_property_owner(uuid),public.app_is_neighborhood_admin(uuid),public.app_has_community_access(uuid),public.activate_my_community_participation(uuid,boolean,boolean),public.set_my_community_preferences(uuid,boolean,boolean),public.leave_community(uuid),public.set_community_rules(uuid,boolean,boolean),public.set_my_community_route_point(uuid,uuid,boolean,integer),public.get_path_to_property_points(uuid),public.get_community_dashboard(uuid),public.get_community_devices(uuid),public.get_community_participants(uuid),public.report_community_maintenance(uuid,text,text,text),public.update_community_maintenance_status(uuid,text),public.get_community_maintenance(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.app_is_property_owner(uuid),public.app_is_neighborhood_admin(uuid),public.app_has_community_access(uuid),public.activate_my_community_participation(uuid,boolean,boolean),public.set_my_community_preferences(uuid,boolean,boolean),public.leave_community(uuid),public.set_community_rules(uuid,boolean,boolean),public.set_my_community_route_point(uuid,uuid,boolean,integer),public.get_path_to_property_points(uuid),public.get_community_dashboard(uuid),public.get_community_devices(uuid),public.get_community_participants(uuid),public.report_community_maintenance(uuid,text,text,text),public.update_community_maintenance_status(uuid,text),public.get_community_maintenance(uuid) TO authenticated;
